-- Normalized reusable special abilities for the curated Monster Manual III player races.
-- Text is intentionally paraphrased from the source entries; race-specific grants live in 11-traits.sql.

WITH abilities(id,source_page,slug,name,description,rules_text,category,action_type) AS (VALUES
  ('mm3-sa-armand-defensive-stance','10-11','armand-defensive-stance','Defensive Stance','Plant yourself and become exceptionally difficult to dislodge.','As a move action, enter a stance that prevents movement and grants +2 on attack rolls, +2 resistance on saves, and +4 dodge AC. The stance ends when the armand moves.','extraordinary','move'),
  ('mm3-sa-armand-stability','10-11','armand-stability','Stability','Exceptional footing on solid ground or while burrowing.','Gain +4 on ability checks made to resist bull rush or trip attempts while standing on the ground or burrowing.','extraordinary','none'),
  ('mm3-sa-changeling-minor-change-shape','24-25','changeling-minor-change-shape','Minor Change Shape','Alter physical appearance without spellcasting.','At will as a full-round action, physically alter appearance in a manner similar to disguise self. The change lasts until used again; true seeing reveals the natural form. Using it for a disguise grants a +10 circumstance bonus on Disguise checks.','supernatural','full_round'),
  ('mm3-sa-dracotaur-spit-fire','42-43','dracotaur-spit-fire','Spit Fire','Hurl an adhesive glob that ignites in the air.','As a standard action make a ranged touch attack with 20-foot range increment. A direct hit deals 2d6 fire damage and creatures within 5 feet take 1d4 fire splash damage. After using this ability, it cannot be used again for 1 minute.','supernatural','standard'),
  ('mm3-sa-sand-giant-heat-shimmer','58-59','sand-giant-heat-shimmer','Heat Shimmer','Surround yourself with distorting desert heat.','At will as a free action, create a shimmering distortion that functions like blur at caster level 15th.','supernatural','free'),
  ('mm3-sa-sand-giant-spell-like','58-59','sand-giant-spell-like-abilities','Sand Giant Spell-Like Abilities','Innate desert and stone magic.','Once per day each: meld into stone and statue, caster level 15th.','spell_like','standard'),
  ('mm3-sa-goatfolk-pack-fervor','63-64','goatfolk-pack-fervor','Pack Fervor','Fight more fiercely beside another ibixian.','While within 30 feet of another goatfolk, gain +2 morale on attack and damage rolls and +4 morale on saving throws against fear effects.','extraordinary','none'),
  ('mm3-sa-forestkith-discordant-frenzy','64-65','forestkith-discordant-frenzy','Discordant Frenzy','A mob of forestkith goblins unnerves weak foes.','When at least three forestkith goblins attack together, creatures of 2 HD or fewer within 30 feet must save against a Charisma-based mind-affecting fear effect or become shaken for 1d4 rounds. A successful save grants 24-hour immunity to that group effect.','extraordinary','none'),
  ('mm3-sa-forestkith-tree-shape','64-65','forestkith-tree-shape','Tree Shape','Assume the form of a small tree, shrub, or limb.','Transform as the tree shape spell with the source entry limitations. The form cannot be dismissed voluntarily and ends at sunset or when the forestkith takes damage.','supernatural','standard'),
  ('mm3-sa-harssaf-flaming-aura','82-83','harssaf-flaming-aura','Flaming Aura','Radiate furnace-like heat and ignite melee blows.','At will as a free action, create a fiery aura. Creatures within 5 feet take 1d6 fire damage per round, and melee attacks made by the harssaf deal an extra 1d6 fire damage when the weapon can conduct the heat.','supernatural','free'),
  ('mm3-sa-harssaf-sand-pulse','82-83','harssaf-sand-pulse','Sand Pulse','Blast the surrounding area with high-speed sand.','Once per day as a standard action, create a 30-foot-radius spread. Creatures in the area take 3d6 damage and are blinded for 5 rounds; a Constitution-based Reflex save halves the damage and negates blindness. Creatures that do not rely on eyes ignore only the blindness. Harssafs are immune to other harssafs’ sand pulses.','supernatural','standard'),
  ('mm3-sa-harssaf-sand-form','82-83','harssaf-sand-form','Sand Form','Become a mobile pile of sand.','At will as a standard action, assume a sand form similar to gaseous form. The harssaf cannot fly in this form, moves along the ground, and can pass through openings less than one-quarter inch wide.','supernatural','standard'),
  ('mm3-sa-kenku-great-ally','86-87','kenku-great-ally','Great Ally','Cooperate unusually well with allies.','When giving or receiving aid another on an attack roll or skill check, the bonus is +3 instead of +2. Against an opponent flanked by an ally, the kenku gains +4 on attack rolls instead of the normal +2 flanking bonus.','extraordinary','none'),
  ('mm3-sa-kenku-mimicry','86-87','kenku-mimicry','Mimicry','Perfectly imitate familiar sounds and voices.','Mimic familiar sounds, voices, and accents. Imitating a specific individual uses Bluff opposed by Sense Motive for listeners familiar with that voice. This does not grant knowledge of an unknown language.','extraordinary','none'),
  ('mm3-sa-lizardfolk-hold-breath','95-96','lizardfolk-hold-breath','Hold Breath','Remain underwater far longer than most humanoids.','Can hold breath for a number of rounds equal to four times Constitution score before drowning checks begin.','extraordinary','none'),
  ('mm3-sa-poison-dusk-poison-use','96','poison-dusk-poison-use','Poison Use','Handle weapon poison safely.','Never risks accidentally poisoning itself when applying poison to a weapon.','extraordinary','none'),
  ('mm3-sa-poison-dusk-chameleon','96','poison-dusk-chameleon-skin','Chameleon Skin','Shift scale coloration to match surroundings.','When not covered by armor, robes, or similar clothing, gain a +5 racial bonus on Hide checks.','extraordinary','none'),
  ('mm3-sa-lumi-body-of-light','98-99','lumi-body-of-light','Body of Light','Positive-energy physiology resists death and draining effects.','Immune to death spells, magical death effects, energy drain, and negative-energy effects. Lumi also avoid the normal lethal overcharge effect of the Positive Energy Plane described by their entry.','supernatural','none'),
  ('mm3-sa-lumi-clear-vision','98-99','lumi-clear-vision','Clear Vision','Eyes of positive light resist visual assault.','Cannot be blinded or dazzled and is immune to the direct light and color effects listed in the source entry, including color spray, rainbow pattern, searing light, sunbeam, and sunburst.','extraordinary','none'),
  ('mm3-sa-lumi-floating-head','98-99','lumi-floating-head','Floating Head','A detached floating head changes how the body can be attacked.','Enemies do not gain the normal +2 attack bonus for flanking a lumi. The lumi is also immune to decapitation by vorpal weapons and to strangling and suffocation effects that depend on a normal neck or airway.','extraordinary','none'),
  ('mm3-sa-lumi-spell-like','98-99','lumi-spell-like-abilities','Lumi Spell-Like Abilities','Positive-energy innate magic.','At will: disrupt undead and light. Three times per day: cure light wounds and glitterdust. Caster level 3rd; save DCs are Charisma-based.','spell_like','standard'),
  ('mm3-sa-nycter-hunting-cry','112-113','nycter-hunting-cry','Hunting Cry','Emit a piercing sonic cone that can paralyze prey.','Once every 2d4 rounds, emit a 30-foot cone dealing 2d4 sonic damage and potentially paralyzing targets for 1d4+1 rounds. A Constitution-based Fortitude save halves the damage and negates paralysis; a successful save grants 24-hour immunity to that nycter’s cry. This is a sonic mind-affecting ability.','supernatural','standard'),
  ('mm3-sa-nycter-blindsense','112-113','nycter-blindsense','Blindsense 60 ft.','Use echolocation to locate nearby creatures.','Blindsense out to 60 feet through echolocation. Creatures not actually seen still retain total concealment.','extraordinary','none'),
  ('mm3-sa-skullcrusher-rock-throwing','116-117','skullcrusher-rock-throwing','Rock Throwing','Throw heavy stones with giant-trained accuracy.','Gain +1 racial bonus on attack rolls when throwing rocks. A skullcrusher can throw 40- to 50-pound Small rocks with a 100-foot range increment, up to five range increments.','extraordinary','none'),
  ('mm3-sa-quaraphon-bellow','128-129','quaraphon-deafening-bellow','Deafening Bellow','Unleash a devastating two-mouthed roar.','Once per day, creatures within 60 feet take 2d6 sonic damage and must make a Constitution-based Fortitude save or become deafened for 1d6 rounds.','supernatural','standard'),
  ('mm3-sa-naztharune-detect-thoughts','136-137','naztharune-detect-thoughts','Detect Thoughts','Continuously sense nearby surface thoughts.','Continuously use detect thoughts as a supernatural ability at caster level 18th. It can be suppressed or resumed as a free action; the player-character save DC is 15 + Charisma modifier.','supernatural','free'),
  ('mm3-sa-naztharune-change-shape','136-137','naztharune-change-shape','Change Shape','Assume humanoid forms at will.','Assume any humanoid form or return to natural form as a standard action. The altered form loses the natural claw attacks; true seeing reveals the natural form.','supernatural','standard'),
  ('mm3-sa-naztharune-shadow-jump','136-137','naztharune-shadow-jump','Shadow Jump','Travel instantly between areas of shadow.','Move between shadows as dimension door, with both origin and destination in at least some shadow. The racial daily allowance is 20 feet, divided among one or more jumps.','supernatural','standard'),
  ('mm3-sa-shifter-shifting','150-151','shifter-shifting','Shifting','Manifest a short burst of lycanthropic power.','Once per day as a free action, shift for 3 + Constitution modifier rounds. The chosen shifter trait supplies the temporary ability bonus and its associated benefit; shifter feats can extend duration and increase uses.','supernatural','free'),
  ('mm3-sa-crystalline-rend','178','crystalline-troll-rend','Rend','Tear a foe struck by both claws.','If both claw attacks hit the same opponent, deal additional rend damage equal to 2d6 plus one-and-one-half times Strength modifier.','extraordinary','none'),
  ('mm3-sa-crystalline-regeneration','178','crystalline-troll-regeneration','Regeneration 5','Rapidly recover from most wounds.','Regeneration 5. Sonic attacks deal normal damage. Severed limbs regrow in 3d6 minutes or can be reattached immediately by holding them to the stump.','extraordinary','none'),
  ('mm3-sa-living-construct','191-193','living-construct-traits-mm3','Living Construct Traits','A sentient construct that combines living and construct rules.','Has a Constitution score; does not gain ordinary construct darkvision or low-light vision; is not immune to mind-affecting effects; has the living-construct immunities and healing limitations; can run, can be raised or resurrected, does not need to eat, sleep, or breathe, and is affected by effects that target living creatures or constructs as described in the source glossary.','extraordinary','none'),
  ('mm3-sa-charger-adamantine-fists','191-192','warforged-charger-adamantine-fists','Adamantine Fists','Hammerlike fists count as adamantine.','Natural slam attacks are treated as adamantine for overcoming damage reduction and object hardness.','extraordinary','none'),
  ('mm3-sa-charger-adamantine-plating','191-192','warforged-charger-adamantine-plating','Adamantine Plating','Heavy integrated adamantine body armor.','Integrated plating grants +8 armor, damage reduction 2/adamantine, 35% arcane spell failure, maximum Dexterity bonus +1, and armor check penalty -5. It counts as heavy armor, prevents wearing normal armor or magic robes, and can itself be enchanted as armor.','extraordinary','none'),
  ('mm3-sa-charger-moderate-fortification','191-192','warforged-charger-moderate-fortification','Moderate Fortification','Integrated construction can negate critical precision.','When subjected to a critical hit or sneak attack, there is a 75% chance the extra critical or sneak-attack damage is negated and normal damage is rolled instead.','extraordinary','none'),
  ('mm3-sa-scout-composite-plating','193','warforged-scout-composite-plating','Composite Plating','Integrated protective plating.','Integrated plating grants +2 armor and 5% arcane spell failure. It occupies the armor/robe body space, prevents wearing normal armor or magic robes, and can be enchanted as armor.','extraordinary','none'),
  ('mm3-sa-scout-light-fortification','193','warforged-scout-light-fortification','Light Fortification','Integrated construction sometimes negates precision damage.','When subjected to a critical hit or sneak attack, there is a 25% chance the extra critical or sneak-attack damage is negated and normal damage is rolled instead.','extraordinary','none'),
  ('mm3-sa-witchknife-psionics','194-195','witchknife-psionics','Psionics','Innate command-oriented psionic spell-like powers.','At will: command, message, and silence (self only; dismissible). Once per day: greater command. Effective caster level 9th and save DCs are Charisma-based.','psi_like','standard'),
  ('mm3-sa-witchknife-sneak-attack','194-195','witchknife-sneak-attack','Sneak Attack +2d6','Strike vulnerable foes for extra precision damage.','Deals +2d6 sneak attack damage when the target is denied Dexterity bonus to AC or is flanked, following the normal sneak attack rules.','extraordinary','none')
)
INSERT INTO dnd35_special_abilities
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,action_type,effects,parameters)
SELECT id,'mm3-3.5',source_page,slug,name,description,rules_text,0,NULL,1,category,action_type,NULL,NULL
FROM abilities
WHERE 1
ON CONFLICT(id) DO UPDATE SET
  source_id=excluded.source_id,
  source_page=excluded.source_page,
  slug=excluded.slug,
  name=excluded.name,
  description=excluded.description,
  rules_text=excluded.rules_text,
  is_homebrew=0,
  owner_user_id=NULL,
  is_enabled=1,
  category=excluded.category,
  action_type=excluded.action_type,
  effects=NULL,
  parameters=NULL;
